import { call } from "../api/client";
import type { NewReview, Review } from "../api/types";
import type { Outcome } from "./result";

/** Submit a review for a product. */
export async function addReview(
  baseUrl: string,
  sku: string,
  rating: number,
  text: string,
): Promise<Outcome<Review>> {
  const body: NewReview = { rating, text };
  try {
    return await call<Review>(baseUrl, "POST", `/products/${encodeURIComponent(sku)}/reviews`, { body });
  } catch {
    return { ok: false, error: { kind: "TransportError" } };
  }
}
