"""Product reviews, listed in the order they were written."""

from fastapi import APIRouter
from pydantic import BaseModel, ConfigDict, Field

from .catalog import find_product
from .db import transaction
from .errors import ApiError
from .schemas import SafeInt

router = APIRouter()


class NewReview(BaseModel):
    model_config = ConfigDict(extra="forbid")

    rating: int = Field(strict=True, ge=1, le=5)
    text: str = Field(strict=True, max_length=500, pattern=r"[^ \t\n]")


class Review(NewReview):
    id: SafeInt
    sku: str


@router.post("/products/{sku}/reviews")
def add_review(sku: str, body: NewReview) -> Review:
    with transaction() as conn:
        if find_product(conn, sku) is None:
            raise ApiError("Missing", sku=sku)
        review_id = conn.execute(
            "INSERT INTO reviews (sku, rating, text) VALUES (?, ?, ?)",
            (sku, body.rating, body.text),
        ).lastrowid
        assert review_id is not None
        return Review(id=review_id, sku=sku, rating=body.rating, text=body.text)


@router.get("/products/{sku}/reviews")
def list_reviews(sku: str) -> list[Review]:
    with transaction() as conn:
        if find_product(conn, sku) is None:
            raise ApiError("Missing", sku=sku)
        return [
            Review(id=row["id"], sku=sku, rating=row["rating"], text=row["text"])
            for row in conn.execute(
                "SELECT id, rating, text FROM reviews WHERE sku = ? ORDER BY id",
                (sku,),
            )
        ]
